CREATE TABLE monthly_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),barber_id uuid NOT NULL,name text NOT NULL,price_cents integer NOT NULL CHECK(price_cents>=0),days integer[] NOT NULL CHECK(cardinality(days)>0 AND days <@ ARRAY[0,1,2,3,4,5,6]),FOREIGN KEY(tenant_id,barber_id) REFERENCES barbers(tenant_id,id));
CREATE TABLE monthly_plan_services(tenant_id uuid NOT NULL,plan_id uuid NOT NULL REFERENCES monthly_plans(id),service_id uuid NOT NULL,outside_price_cents integer CHECK(outside_price_cents>=0),PRIMARY KEY(plan_id,service_id),FOREIGN KEY(tenant_id,service_id) REFERENCES services(tenant_id,id));
CREATE TABLE client_memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),client_id uuid NOT NULL,plan_id uuid NOT NULL REFERENCES monthly_plans(id),starts_on date NOT NULL,ends_on date NOT NULL CHECK(ends_on>=starts_on),FOREIGN KEY(tenant_id,client_id) REFERENCES clients(tenant_id,id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['monthly_plans','monthly_plan_services','client_memberships'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING(tenant_id=NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid)',t); EXECUTE format('GRANT SELECT,INSERT ON %I TO barberhub_app',t); END LOOP; END $$;
